import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"检查与故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"operations/troubleshooting.md","filePath":"operations/troubleshooting.md","lastUpdated":1788621106000}`),a={name:`operations/troubleshooting.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="检查与故障排查" tabindex="-1">检查与故障排查 <a class="header-anchor" href="#检查与故障排查" aria-label="Permalink to “检查与故障排查”">​</a></h1><h2 id="推荐顺序" tabindex="-1">推荐顺序 <a class="header-anchor" href="#推荐顺序" aria-label="Permalink to “推荐顺序”">​</a></h2><ol><li>记录发生时间、账号、页面路径和操作步骤。</li><li>用 <code>docker compose ps</code> 确认容器和健康状态。</li><li>查看同一时间段对应服务日志，保留第一条错误。</li><li>检查宿主机反向代理、网络、磁盘、数据库、Redis 和 DNS。</li><li>修复根因后再重启；不要用持续重启掩盖错误。</li></ol><h2 id="页面、logo-或菜单异常" tabindex="-1">页面、Logo 或菜单异常 <a class="header-anchor" href="#页面、logo-或菜单异常" aria-label="Permalink to “页面、Logo 或菜单异常”">​</a></h2><p>Logo 不显示时检查静态文件是否进入镜像、响应状态与 <code>Content-Type</code>、文件和父目录读取权限，以及 CDN/浏览器缓存。应用位于 <code>/app/</code>，静态资源必须使用正确基础路径。</p><p>版本刚更新时，旧标签页可能引用已经删除的 JS 分块，表现为侧边栏个别菜单点击没反应。先强制刷新；路由内置一次分块加载失败刷新。仍失败时查看浏览器网络面板是否有旧资源 <code>404</code>，并清理代理/CDN 的 HTML 缓存。</p><p><code>www</code> 或 <code>mail</code> 的网页若打开成服务器上另一个站点，检查每个主机名是否有明确虚拟主机和默认回退，不能只依赖第一个 server block。</p><p>企业域名没有显示组织品牌时，先在组织域名页确认所有权 TXT 与 MX 均已验证；待验证域名即使已添加并启用，也不会用于品牌匹配。再检查全局企业品牌开关、访问 Host、组织状态、企业套餐状态、组织品牌内容和 Logo 响应。组织被暂停或没有生效/宽限期套餐时，公开页面会恢复平台品牌。</p><h2 id="登录或注册失败" tabindex="-1">登录或注册失败 <a class="header-anchor" href="#登录或注册失败" aria-label="Permalink to “登录或注册失败”">​</a></h2><ul><li>区分普通登录页与带 <code>redirect=/admin</code> 的管理员入口。</li><li>检查账号启用状态、密码、TOTP 时间和登录限流。</li><li>管理员账号不会进入普通用户首次引导；已有邮箱的用户也不应重复进入创建邮箱步骤。</li><li>OAuth 检查提供方开关、客户端配置、回调地址、一次性 state 和 Turnstile 证明。</li><li>注册检查开放注册、邮件验证、来源 IP 限速和 SMTP 认证邮件。</li></ul><p>管理员密码采用哈希保存，无法从数据库读取明文。忘记后走受控重置，并立即设置新密码。</p><h2 id="turnstile-没有出现交互" tabindex="-1">Turnstile 没有出现交互 <a class="header-anchor" href="#turnstile-没有出现交互" aria-label="Permalink to “Turnstile 没有出现交互”">​</a></h2><p>托管模式可能自动完成无感验证。查看组件是否加载、按钮是否等待令牌、请求是否携带 <code>turnstile_token</code> 和 Cloudflare 是否记录统计。</p><p>若页面显示 Site Key，但后台显示 Secret 未配置，补齐 Secret 后保存。启用但配置不完整或 Cloudflare 不可达时，系统按故障关闭返回 503。紧急恢复时在服务器环境中显式设置 <code>TURNSTILE_ENABLED=false</code>（也接受 <code>0</code>、<code>no</code> 或 <code>off</code>）并重启后端；它会临时覆盖数据库启用状态，即使数据库设置暂时无法读取也能救援。空值或拼写错误不会覆盖数据库中已经启用的保护，数据库设置查询失败时仍会故障关闭。修复后移除覆盖值并再次重启。</p><h2 id="smtp-认证邮件发送失败" tabindex="-1">SMTP 认证邮件发送失败 <a class="header-anchor" href="#smtp-认证邮件发送失败" aria-label="Permalink to “SMTP 认证邮件发送失败”">​</a></h2><p>依次核对：</p><ol><li>主机名没有 <code>http://</code>、路径或空格。</li><li>465 对应 SSL/TLS，587 对应 STARTTLS。</li><li>用户名与 SMTP 专用密码/API Key 正确。</li><li>系统发件人是服务商已验证并允许的完整地址。</li><li>宿主机能连接目标端口，服务商账号没有欠费、冻结或超额。</li><li>发信域名 SPF、DKIM 和 DMARC 按服务商要求配置。</li></ol><p>使用“测试成功后保存”可保证失败候选值不覆盖旧配置。系统 SMTP 失败不会回退为本服务器直接发信。完整说明见 <a href="/nodemail-docs/admin/registration-smtp-turnstile">注册、SMTP 认证邮件与 Turnstile</a>。</p><h2 id="nodeloc-等级显示不对" tabindex="-1">NodeLoc 等级显示不对 <a class="header-anchor" href="#nodeloc-等级显示不对" aria-label="Permalink to “NodeLoc 等级显示不对”">​</a></h2><ul><li>注册来源只看账号最初由哪个提供方创建。</li><li>实际会员等级只看该账号在 <code>oauth_account_bindings.external_level_code</code> 保存的 <code>TL0</code>–<code>TL4</code>，不回退 <code>users.level</code>。</li><li>本站配额等级显示 <code>L0</code>–<code>L4</code>，不能拿来推断 NodeLoc 等级。</li><li>“等级待同步”表示绑定存在但缺少可信等级，可重新授权同一个 NodeLoc 身份。</li><li>检查后台 TL 到 L 映射和“登录时同步第三方等级”。</li></ul><p>普通账号绑定 NodeLoc 后仍显示普通账号，同时增加真实 NodeLoc 等级，这是预期行为。</p><h2 id="重复进入首次引导" tabindex="-1">重复进入首次引导 <a class="header-anchor" href="#重复进入首次引导" aria-label="Permalink to “重复进入首次引导”">​</a></h2><p>检查当前会话的用户 ID、邮箱列表接口和引导完成判断。地址提示“已被使用”通常说明邮箱已经创建，但旧前端仍停在引导路由。强制刷新后应按服务器实际邮箱状态进入收件箱。管理员应直接转到后台概览。</p><h2 id="邮件客户端无法连接" tabindex="-1">邮件客户端无法连接 <a class="header-anchor" href="#邮件客户端无法连接" aria-label="Permalink to “邮件客户端无法连接”">​</a></h2><p>推荐配置：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IMAP: mail.to9.us:993 SSL/TLS</span></span>
<span class="line"><span>POP3: mail.to9.us:995 SSL/TLS</span></span>
<span class="line"><span>SMTP: mail.to9.us:587 STARTTLS</span></span>
<span class="line"><span>用户名: 完整邮箱地址</span></span>
<span class="line"><span>密码: 应用专用密码</span></span></code></pre></div><p>分别检查端口、TLS 主机名与有效期、账号和邮箱状态、协议访问开关、应用专用密码及限速。网页可用不能证明邮件端口正常。</p><h2 id="收不到邮件" tabindex="-1">收不到邮件 <a class="header-anchor" href="#收不到邮件" aria-label="Permalink to “收不到邮件”">​</a></h2><p>检查 MX、25 端口、邮箱接收开关、容量、Catch-All、收信规则、垃圾邮件文件夹、“被拦截邮件”和 rspamd，再查看 SMTP 日志。启用高风险隔离后，达到阈值的来信会保留完整原文供邮箱所有者净化预览、放行或永久删除；升级前的历史记录没有正文，只能删除。发件域 DMARC <code>p=reject</code> 验证失败仍可能直接拒绝。同一上游在短时间重试的重复副本会被指纹识别；若担心误去重，按邮箱、原始哈希和时间窗口核查。</p><h2 id="邮箱转发没有到达" tabindex="-1">邮箱转发没有到达 <a class="header-anchor" href="#邮箱转发没有到达" aria-label="Permalink to “邮箱转发没有到达”">​</a></h2><p>先确认原始来信已保存在本地邮箱，再检查外部地址格式、是否与源邮箱相同、域名发信资格、用户每日额度、能量、出站通道和邮件流转失败原因。邮箱设置可转到任意有效外部邮箱；收信规则只允许当前已验证的本人找回邮箱。自动生成或已经转发过的邮件会跳过，邮箱设置与规则的相同目标会合并为一次。转发是本地收信后的独立外发，外发失败不会撤回本地邮件。</p><h2 id="业务发信失败" tabindex="-1">业务发信失败 <a class="header-anchor" href="#业务发信失败" aria-label="Permalink to “业务发信失败”">​</a></h2><p>检查域名发信资格、用户申请、每日收件人数额度、能量、黑名单/抑制、出站通道状态、通道小时/每日额度和远端响应。个人邮箱查用户今日额度与能量；企业邮箱查组织套餐状态和全组织今日共享额度，它不会扣受派成员个人额度。系统 SMTP 认证邮件与业务出站通道是两套配置，不要在错误页面反复修改。</p><p>临时失败等待重试；永久拒绝根据远端响应修正。客户端超时后先查已发送和邮件流转，避免重复投递。</p><h2 id="tls-证书没有更新" tabindex="-1">TLS 证书没有更新 <a class="header-anchor" href="#tls-证书没有更新" aria-label="Permalink to “TLS 证书没有更新”">​</a></h2><p>比较磁盘证书与 587、993、995 实际握手证书的序列号、SAN 和到期时间。续期后必须重新加载后端；只重载网页 Nginx 不会更新邮件协议证书。</p><p>同时验证根域、<code>www</code> 和邮件 Web 主机的 HTTPS 行为，确保没有证书不匹配或落到其他虚拟主机。</p><h2 id="迁移失败" tabindex="-1">迁移失败 <a class="header-anchor" href="#迁移失败" aria-label="Permalink to “迁移失败”">​</a></h2><p>保留第一条迁移错误和前后日志。050、058、062 和 063 会在 OAuth 身份、计费所有者或已验证找回邮箱存在歧义时停止。不要删除迁移记录或强行跳过；先在备份副本定位冲突，明确归属后再重新升级。</p><h2 id="订单未到账" tabindex="-1">订单未到账 <a class="header-anchor" href="#订单未到账" aria-label="Permalink to “订单未到账”">​</a></h2><p>按订单号核对支付平台交易、回调签名、金额、币种、订单所有者、状态、钱包流水和订阅。使用幂等补偿，不能因为用户截图就重复手工加款。</p><h2 id="提交工单需要的信息" tabindex="-1">提交工单需要的信息 <a class="header-anchor" href="#提交工单需要的信息" aria-label="Permalink to “提交工单需要的信息”">​</a></h2><p>提供发生时间、账号或邮箱、页面路径、操作步骤、订单号或邮件 ID，以及去除敏感信息后的错误文字。不要提交密码、API Key、Cookie、验证码、支付密钥、SMTP 密码或 TLS 私钥。</p>`,43)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};